#include <stdio.h>
#include <sqlite3.h>

int main() {
    sqlite3 db;
    sqlite3stmt res;
    int rc = sqlite3open("health.db", &db);

    if (rc != SQLITEOK) {
        fprintf(stderr, "Cannot open database: %s\n", sqlite3errmsg(db));
        return 1;
    }

    const char sql = "SELECT patientid, heartrate, bloodpressure FROM healthdata;";

    rc = sqlite3preparev2(db, sql, -1, &res, 0);

    if (rc != SQLITEOK) {
        fprintf(stderr, "Failed to fetch data: %s\n", sqlite3errmsg(db));
        sqlite3close(db);
        return 1;
    }

    printf("PatientID | HeartRate | BloodPressure\n");
    printf("-------------------------------------\n");

    while (sqlite3step(res) == SQLITEROW) {
        int patientid = sqlite3columnint(res, 0);
        int heartrate = sqlite3columnint(res, 1);
        const unsigned char bloodpressure = sqlite3columntext(res, 2);

        printf("%9d | %9d | %s\n", patientid, heartrate, bloodpressure);
    }

    sqlite3finalize(res);
    sqlite3close(db);

    return 0;
}

Step 5: Note this code is purely educational and requires an existing SQLite database file "health.db" with a table "healthdata" containing columns patientid, heartrate, bloodpressure.

